INSERT INTO `Service` VALUES (1,'Классическая мужская стрижка','Профессиональная стрижка с учётом индивидуальных особенностей лица и структуры волос. Включает мытьё головы, сушку и укладку.',1,1500.00,60),(2,'Стрижка машинкой (бокс/полубокс)','Аккуратная стрижка машинкой с чёткими контурами и окантовкой. Подходит для коротких волос, выполняется без сложных укладок.',1,1000.00,40),(3,'Укладка волос со стайлингом','Создание стильной укладки с использованием профессиональных средств (воск, помада, гель). Подчёркивает форму стрижки и придаёт завершённый вид.',1,500.00,20),(4,'Мытьё головы с маской','Глубокое очищение волос шампунем и нанесение питательной маски. Устраняет сухость, придаёт блеск и облегчает укладку.',1,400.00,15),(5,'Окрашивание волос (полное)','Равномерное окрашивание волос в выбранный оттенок с использованием профессиональной краски. Позволяет освежить образ или скрыть седину.',1,2500.00,90),(6,'Камуфляж седины','Точечное тонирование седых волос в натуральный оттенок без изменения общего цвета. Эффект держится 4–6 недель.',1,1800.00,45),(7,'Детская стрижка (до 14 лет)','Безопасная стрижка для мальчиков с учётом детской структуры волос. Выполняется аккуратно, с минимизацией стресса для ребёнка.',1,800.00,30),(8,'Стрижка под насадку','Стрижка машинкой с использованием насадок разной длины (3–12 мм). Быстрый и практичный вариант для поддержания формы.',1,700.00,25),(9,'Фэйд (fade) с плавным переходом','Создание плавного перехода от коротких волос к длинным с эффектом «растаявших» контуров. Требует высокой точности.',1,1700.00,50),(10,'Кроп-стрижка','Современная стрижка с объёмом на макушке и короткими боками. Подходит для прямых или слегка вьющихся волос.',1,1600.00,55),(11,'Британка','Классическая стрижка с удлинённой чёлкой и объёмом на макушке. Требует регулярной укладки.',1,1650.00,55),(12,'Канадка','Стрижка с объёмом на лбу и макушке, укороченными висками и затылком. Подходит для густых волос.',1,1700.00,60),(13,'Топ-нот','Стрижка с удлинённой макушкой, собранной в пучок, и очень короткими висками/затылком. Креативный вариант.',1,1800.00,65),(14,'Коррекция стрижки','Подравнивание кончиков, уточнение формы и окантовка. Выполняется для поддержания аккуратного вида между основными стрижками.',1,600.00,20),(15,'Глубокое очищение кожи головы','Процедура с использованием скраба для кожи головы. Удаляет излишки кожного сала, улучшает кровообращение и стимулирует рост волос.',1,700.00,25),(16,'Стрижка с текстурированием','Создание текстуры волос с помощью филировки и градуировки. Придаёт объём и лёгкую небрежность.',1,1400.00,50),(17,'Стрижка с асимметрией','Асимметричная стрижка с разной длиной волос по бокам. Стильный вариант для креативных клиентов.',1,1600.00,55),(18,'Стрижка под ноль (налысо)','Полное удаление волос машинкой. Выполняется с окантовкой висков и шеи.',1,500.00,15),(19,'Экспресс-стрижка (без мытья)','Быстрая стрижка без мытья головы. Подходит для поддержания формы между полноценными процедурами.',1,800.00,30),(20,'Стрижка бороды','Придание формы и длины бороде с учётом пожеланий клиента и особенностей лица. Включает окантовку и выравнивание контуров.',2,800.00,30),(21,'Моделирование бороды','Комплексная работа по созданию индивидуального силуэта бороды. Мастер подбирает форму, подчёркивающую черты лица, и выполняет точную стрижку.',2,1200.00,45),(22,'Оформление контура бороды','Чёткая окантовка линии роста волос на шее и щеках. Придаёт бороде ухоженный вид и аккуратность.',2,500.00,15),(23,'Уход за бородой (маска + масло)','Нанесение питательной маски для бороды с последующим массажем и обработкой специальным маслом. Увлажняет волосы, смягчает кожу под бородой.',2,700.00,25),(24,'Окрашивание бороды','Выравнивание цвета бороды, камуфляж седины или креативное окрашивание. Используется стойкая краска, безопасная для кожи.',2,1500.00,40),(25,'Королевское бритьё опасной бритвой','Многоэтапная процедура: распаривание лица, бритьё опасной бритвой, холодный компресс и уход после бритья. Обеспечивает идеально гладкую кожу.',2,2000.00,60),(26,'Бритьё шейвером','Быстрое и комфортное удаление щетины электрической бритвой. Подходит для ежедневного ухода, минимизирует раздражение.',2,600.00,20),(27,'Коррекция усов','Придание формы усам, подравнивание кончиков и окантовка.',2,400.00,10),(28,'Оформление линии бороды на шее','Чёткое оформление нижней границы бороды с использованием триммера.',2,300.00,10),(29,'Подравнивание бороды триммером','Быстрое подравнивание длины бороды без сложной коррекции формы.',2,400.00,15),(30,'Глубокий уход за бородой','Комплекс: пилинг для кожи под бородой + маска + масло + массаж. Восстанавливает здоровье волос и кожи.',2,1200.00,40),(31,'Восковое моделирование бороды','Фиксация формы бороды с помощью воска для укладки. Создаёт эффект «зачёсанной» бороды.',2,350.00,10),(32,'Удаление волос в носу и ушах триммером','Аккуратное удаление лишних волос в носу и ушах без боли и раздражения.',2,300.00,10),(33,'Контурная стрижка бороды','Точная стрижка с созданием чётких геометрических линий.',2,900.00,35),(34,'Распаривание лица перед бритьём','Глубокое распаривание кожи с помощью горячего полотенца. Открывает поры, смягчает щетину и подготавливает лицо к бритью.',3,300.00,10),(35,'Массаж лица','Расслабляющий массаж лица с использованием питательного крема. Улучшает кровообращение, снимает напряжение и придаёт коже здоровый вид.',3,800.00,20),(36,'Маска для лица (увлажняющая/успокаивающая)','Нанесение профессиональной маски для глубокого увлажнения или успокоения кожи после бритья. Снимает раздражение и восстанавливает баланс.',3,600.00,25),(37,'Пилинг для лица','Очищение кожи от ороговевших клеток с помощью скраба или химического пилинга. Улучшает текстуру кожи, выравнивает тон и стимулирует обновление.',3,900.00,30),(38,'Компресс после бритья','Нанесение успокаивающего лосьона и холодного компресса для снятия раздражения после бритья.',3,400.00,15),(39,'Очищение пор','Глубокое очищение пор с использованием специальных средств. Уменьшает чёрные точки и улучшает состояние кожи.',3,700.00,25),(40,'Увлажнение кожи лица','Нанесение интенсивного увлажняющего крема или сыворотки. Восстанавливает водный баланс кожи.',3,500.00,15),(41,'Антистресс-уход для лица','Комплекс: массаж + маска + увлажнение. Расслабляет, снимает напряжение, улучшает цвет лица.',3,1500.00,45),(42,'Чёрная маска для глубокого очищения','Очищающая маска на основе угля. Вытягивает загрязнения из пор, матирует кожу.',3,800.00,30),(43,'Тонизирование кожи','Нанесение тонизирующего лосьона для восстановления pH-баланса кожи после процедур.',3,200.00,5),(44,'Мужской маникюр (классический)','Обрезной маникюр с обработкой кутикулы, приданием формы ногтям и полировкой. Завершается нанесением увлажняющего крема.',4,1200.00,40),(45,'Педикюр (мужской)','Уход за ногтями и кожей стоп: удаление огрубевшей кожи, обработка ногтей, массаж с кремом. Придаёт ногам ухоженный вид.',4,1800.00,60),(46,'Депиляция воском (нос/уши)','Удаление нежелательных волос в носу и ушах с помощью воска. Обеспечивает длительный эффект и аккуратный внешний вид.',4,500.00,15),(47,'Коррекция бровей (триммер/выщипывание)','Придание бровям аккуратной формы с помощью триммера или пинцета. Включает удаление лишних волос и оформление контура.',4,400.00,15),(48,'Мужской маникюр аппаратный','Аппаратный маникюр без обрезания кутикулы. Более безопасный и щадящий метод.',4,1300.00,45),(49,'Мужской педикюр аппаратный','Аппаратная обработка стоп и ногтей. Меньше травматичен, подходит для чувствительной кожи.',4,2000.00,70),(50,'Комплексный мужской уход (маникюр + педикюр)','Полный уход за руками и ногами: обработка ногтей, кутикулы, кожи стоп, массаж и увлажнение.',4,3000.00,90),(51,'Депиляция воском (грудь/спина)','Удаление волос на груди или спине с помощью воска. Длительный эффект до 3–4 недель.',4,1500.00,45),(52,'Коррекция бровей с окрашиванием','Оформление формы бровей + окрашивание хной или краской. Придаёт выразительность взгляду.',4,700.00,30);
